package dustin.cex.domains.kyc;
import dustin.cex.domains.account.*;
import dustin.cex.domains.auth.model.entity.RefreshToken;
import dustin.cex.domains.auth.model.dto.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.system.*;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** 실제 해시·세션·JWT·동시 요청·감사 롤백으로 자격 변경의 전체 확정을 검증한다. */
@ExtendWith(OutputCaptureExtension.class)
class CustomerPasswordChangeIntegrationTest extends EddTestSupport {
    static final String OLD="security-test-password",NEW="independent-new-passphrase-2026";
    @Autowired CustomerPasswordChange changes;
    CustomerPasswordChange.Receipt change(String old,String next){return changes.change(customer.getId(),sid,new CustomerPasswordChange.Input(old,next,null));}
    @Test void successChangesHashRevokesAllAndRecordsOneEvent() throws Exception {var extra=tokens.saveAndFlush(RefreshToken.builder().userId(customer.getId()).tokenHash(sha(UUID.randomUUID().toString())).expiresAt(LocalDateTime.now().plusHours(1)).build());var r=change(OLD,NEW);assertTrue(r.requiresLogin());var u=users.findById(customer.getId()).orElseThrow();assertTrue(passwords.verify(NEW,u.getPasswordHash()));assertFalse(passwords.verify(OLD,u.getPasswordHash()));assertEquals(0,tokens.countValidByUserId(customer.getId(),LocalDateTime.now()));assertTrue(tokens.findBySessionId(extra.getSessionId()).orElseThrow().getRevoked());mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+customerAccess)).andExpect(status().isUnauthorized());assertEquals(customer.getEmail(),auth.signin(new SigninRequest(customer.getEmail(),NEW)).getUser().getEmail());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_password_changes WHERE user_id=?",Long.class,customer.getId()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_password_changes WHERE id=? AND session_id<>?",Long.class,r.id(),sid));}
    @Test void wrongCurrentDoesNotChangeHashOrSessions(){assertEquals(403,assertThrows(ResponseStatusException.class,()->change("wrong-current-password",NEW)).getStatusCode().value());assertTrue(passwords.verify(OLD,users.findById(customer.getId()).orElseThrow().getPasswordHash()));assertFalse(tokens.findBySessionId(sid).orElseThrow().getRevoked());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_password_changes WHERE user_id=?",Long.class,customer.getId()));}
    @Test void fiveWrongAttemptsAreDurableAndBoundFurtherChanges(){for(int i=0;i<5;i++)assertEquals(403,assertThrows(ResponseStatusException.class,()->change("wrong-current-password",NEW)).getStatusCode().value());assertEquals(429,assertThrows(ResponseStatusException.class,()->change(OLD,NEW)).getStatusCode().value());assertFalse(tokens.findBySessionId(sid).orElseThrow().getRevoked());assertEquals(5,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE actor_id=? AND action='CUSTOMER_PASSWORD_CHANGE' AND detail='WRONG_PASSWORD'",Long.class,customer.getId()));}
    @Test void weakSameAndInvalidInputsAreRejected(){for(String next:List.of("short",OLD,"x".repeat(257),"bad\nnew-password-value"))assertEquals(400,assertThrows(ResponseStatusException.class,()->change(OLD,next)).getStatusCode().value());assertThrows(ResponseStatusException.class,()->changes.change(customer.getId(),sid,null));assertFalse(tokens.findBySessionId(sid).orElseThrow().getRevoked());}
    @Test void auditFailureRollsBackHashSessionsAndEvent(){doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_PASSWORD_CHANGED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->change(OLD,NEW));reset(audit);assertTrue(passwords.verify(OLD,users.findById(customer.getId()).orElseThrow().getPasswordHash()));assertFalse(tokens.findBySessionId(sid).orElseThrow().getRevoked());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_password_changes WHERE user_id=?",Long.class,customer.getId()));assertNotNull(change(OLD,NEW));}
    @Test void currentSessionCannotChangeAgainAfterSuccess(){change(OLD,NEW);assertThrows(ResponseStatusException.class,()->change(NEW,"another-independent-password"));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_password_changes WHERE user_id=?",Long.class,customer.getId()));}
    @Test void concurrentChangesCommitOnePasswordAndOneEvent() throws Exception {var pool=Executors.newFixedThreadPool(2);try{java.util.concurrent.Callable<Boolean> work=()->{try{change(OLD,NEW);return true;}catch(ResponseStatusException e){return false;}};var a=pool.submit(work);var b=pool.submit(work);assertNotEquals(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_password_changes WHERE user_id=?",Long.class,customer.getId()));}finally{pool.shutdownNow();}}
    @Test void changedPasswordCannotMintOldRefreshSession(){var login=auth.signin(new SigninRequest(customer.getEmail(),OLD));sid=UUID.fromString(jwt.verifyAccessToken(login.getAccessToken()).get("sid",String.class));change(OLD,NEW);assertThrows(dustin.cex.domains.auth.exception.AuthException.class,()->auth.refreshAccessToken(login.getRefreshToken()));}
    @Test void operatorForeignAndDisabledSessionsAreRejected(){var input=new CustomerPasswordChange.Input(OLD,NEW,null);assertThrows(ResponseStatusException.class,()->changes.change(maker.user().getId(),maker.sid(),input));assertThrows(ResponseStatusException.class,()->changes.change(customer.getId(),maker.sid(),input));var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->change(OLD,NEW));}
    @Test void immutableEventsCannotBeUpdatedDeletedOrTruncated(){change(OLD,NEW);for(String sql:List.of("UPDATE customer_password_changes SET id=id","DELETE FROM customer_password_changes","TRUNCATE customer_password_changes"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));}
    @Test void signupAndChangeUseSameNewPasswordPolicy(){assertThrows(dustin.cex.domains.auth.exception.AuthException.class,()->auth.signup(new SignupRequest(UUID.randomUUID()+"@test.invalid","short-password",null)));assertNotNull(auth.signup(new SignupRequest(UUID.randomUUID()+"@test.invalid",NEW,null)));}
    @Test void malformedPasswordDoesNotAppearInLogs(CapturedOutput output) throws Exception {String invalid="sensitive-input-"+UUID.randomUUID()+"x".repeat(257);mvc.perform(post("/api/customer/security/password").header("Authorization","Bearer "+customerAccess).contentType("application/json").content(json.writeValueAsString(new CustomerPasswordChange.Input(OLD,invalid,null)))).andExpect(status().isBadRequest());mvc.perform(post("/api/auth/signup").contentType("application/json").content(json.writeValueAsString(new SignupRequest(UUID.randomUUID()+"@test.invalid",invalid,null)))).andExpect(status().isBadRequest());mvc.perform(post("/api/auth/signin").contentType("application/json").content(json.writeValueAsString(new SigninRequest(customer.getEmail(),invalid)))).andExpect(status().isUnauthorized());assertFalse(output.getAll().contains(invalid));assertFalse(new CustomerPasswordChange.Input(OLD,NEW,null).toString().contains(OLD));}
    @Test void actualHttpReturnsReceiptButNoTokens() throws Exception {String raw=mvc.perform(post("/api/customer/security/password").header("Authorization","Bearer "+customerAccess).contentType("application/json").content(json.writeValueAsString(new CustomerPasswordChange.Input(OLD,NEW,null)))).andExpect(status().isOk()).andExpect(jsonPath("$.requiresLogin").value(true)).andReturn().getResponse().getContentAsString();for(String secret:List.of(OLD,NEW,"accessToken","refreshToken","passwordHash"))assertFalse(raw.contains(secret));}
    @Test void ambientTransactionIsRejected(){assertThrows(org.springframework.transaction.IllegalTransactionStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->change(OLD,NEW)));}
    @Test void explicitAuthFailuresHaveCorrectHttpStatus() throws Exception {mvc.perform(post("/api/auth/signup").contentType("application/json").content(json.writeValueAsString(new SignupRequest(customer.getEmail(),NEW,null)))).andExpect(status().isBadRequest());mvc.perform(post("/api/auth/signin").contentType("application/json").content(json.writeValueAsString(new SigninRequest(customer.getEmail(),"wrong-independent-passphrase")))).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/refresh").contentType("application/json").content("{\"refreshToken\":\"not-a-real-refresh-token\"}")).andExpect(status().isUnauthorized());}
    @Test void pendingOperatorMfaCannotRefreshAndReturnsForbidden() throws Exception {var pending=auth.signin(new SigninRequest(maker.user().getEmail(),OLD));assertTrue(pending.isMfaRequired());mvc.perform(post("/api/auth/refresh").contentType("application/json").content(json.writeValueAsString(Map.of("refreshToken",pending.getRefreshToken())))).andExpect(status().isForbidden());}

    @Test void unregisteredCustomerCannotRequestPasskeyChangeOptions(){assertThrows(ResponseStatusException.class,()->changes.options(customer.getId(),sid,new CustomerPasswordChange.Input(OLD,NEW,null)));}
}
